"""Street Legends frontend: pool table — first house item (Games).
Run from repo root: python3 frontend/patch-house-pool-table.py
Idempotent - safe to re-run.

ADDS:
1. Pool table picture (from the user's image) written to
   frontend/assets/houses/items/pool-table.jpg.
2. Pool Table entry in the Games list (HOUSE_ITEMS) with its picture.
3. Dropdown rows now show the item picture + name + PLACED / TAP TO
   PLACE. Tapping places it in the house (free, counts against the
   house's item limit); tapping a placed item takes it back out.
   Only the house owner sees the toggle work (backend enforces it).
4. api.ts gains addHouseItem / removeHouseItem; index.tsx imports
   them and adds the toggle handler.

FRONTEND change: needs a rebuild + new AAB upload to Play internal
testing. A backend Deploy alone does NOT ship this.
"""
import base64
import sys
from pathlib import Path

POOL_TABLE_B64 = ""

INDEX = Path("frontend/app/(tabs)/index.tsx")
API = Path("frontend/services/api.ts")
ASSET = Path("frontend/assets/houses/items/pool-table.jpg")


def main():
    # 1. Item picture asset.
    ASSET.parent.mkdir(parents=True, exist_ok=True)
    if ASSET.exists() and ASSET.stat().st_size > 0:
        print("SKIP: pool table picture already present")
    else:
        ASSET.write_bytes(base64.b64decode(POOL_TABLE_B64))
        print("OK: pool table picture written")

    # 2. HOUSE_ITEMS Games entry.
    if not INDEX.exists():
        print(f"ERROR: {INDEX} not found. Run from repo root.")
        sys.exit(1)
    src = INDEX.read_text()
    games_old = "  games: [],"
    games_new = "  games: [{ id: 'pool-table', name: 'Pool Table', image: require('../../assets/houses/items/pool-table.jpg') }],"
    if games_new in src:
        print("SKIP: pool table already in Games list")
    elif src.count(games_old) == 1:
        src = src.replace(games_old, games_new, 1)
        print("OK: pool table added to Games list")
    else:
        print(f"WARNING: games anchor matched {src.count(games_old)}x")

    # 3. Toggle handler (after the selection state line).
    handler_old = "  const [selectedHouseItem, setSelectedHouseItem] = useState<any | null>(null);"
    handler_new = """  const [selectedHouseItem, setSelectedHouseItem] = useState<any | null>(null);
  const handleHouseItemToggle = async (item: any) => {
    if (!interiorHouse || !playerId) return;
    const placed = (interiorHouse.items || []).some((it: any) => it.item_id === item.id);
    try {
      const res = placed
        ? await removeHouseItem(interiorHouse.id, playerId, item.id)
        : await addHouseItem(interiorHouse.id, playerId, item.id);
      if (res?.house) {
        setInteriorHouse(res.house);
      } else {
        const next = (interiorHouse.items || []).filter((it: any) => it.item_id !== item.id);
        if (!placed) next.push({ item_id: item.id, name: item.name });
        setInteriorHouse({ ...interiorHouse, items: next });
      }
    } catch (e: any) {
      Alert.alert('Item', e?.response?.data?.detail || e?.message || 'Could not update item.');
    }
  };"""
    if handler_new in src:
        print("SKIP: toggle handler already present")
    elif src.count(handler_old) == 1:
        src = src.replace(handler_old, handler_new, 1)
        print("OK: toggle handler added")
    else:
        print(f"WARNING: handler anchor matched {src.count(handler_old)}x")

    # 4. Dropdown rows: picture + placed state + toggle.
    row_old = """                    (HOUSE_ITEMS[houseItemCategory] || []).map((item: any) => (
                      <TouchableOpacity
                        key={item.id}
                        onPress={() => { setSelectedHouseItem(item); setHouseItemCategory(null); }}
                        style={{ paddingVertical: 10, borderBottomWidth: 1, borderBottomColor: '#222' }}
                      >
                        <Text style={{ color: '#fff', fontWeight: '700' }}>{item.name}</Text>
                      </TouchableOpacity>
                    ))"""
    row_new = """                    (HOUSE_ITEMS[houseItemCategory] || []).map((item: any) => {
                      const placed = (interiorHouse?.items || []).some((it: any) => it.item_id === item.id);
                      return (
                        <TouchableOpacity
                          key={item.id}
                          onPress={() => handleHouseItemToggle(item)}
                          style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 10, borderBottomWidth: 1, borderBottomColor: '#222', gap: 10 }}
                        >
                          {item.image ? (
                            <Image source={item.image} style={{ width: 44, height: 44, borderRadius: 8 }} resizeMode="cover" />
                          ) : null}
                          <Text style={{ color: '#fff', fontWeight: '700', flex: 1 }}>{item.name}</Text>
                          <Text style={{ color: placed ? '#4caf50' : '#f39c12', fontWeight: '800', fontSize: 12 }}>{placed ? '✓ PLACED' : 'TAP TO PLACE'}</Text>
                        </TouchableOpacity>
                      );
                    })"""
    if row_new in src:
        print("SKIP: dropdown rows already upgraded")
    elif src.count(row_old) == 1:
        src = src.replace(row_old, row_new, 1)
        print("OK: dropdown rows show picture + placed state")
    else:
        print(f"WARNING: dropdown row anchor matched {src.count(row_old)}x")
    INDEX.write_text(src)

    # 5. api.ts functions (after sellHouse).
    if not API.exists():
        print(f"WARNING: {API} not found — add addHouseItem/removeHouseItem manually")
    else:
        api = API.read_text()
        sell_old = """export const sellHouse = async (houseId: string, playerId: string): Promise<any> => {
  const response = await api.post(`/houses/${houseId}/sell`, { player_id: playerId });
  return response.data;
};"""
        sell_new = sell_old + """

export const addHouseItem = async (houseId: string, playerId: string, itemId: string): Promise<any> => {
  const response = await api.post(`/houses/${houseId}/items/add`, { player_id: playerId, item_id: itemId });
  return response.data;
};

export const removeHouseItem = async (houseId: string, playerId: string, itemId: string): Promise<any> => {
  const response = await api.post(`/houses/${houseId}/items/remove`, { player_id: playerId, item_id: itemId });
  return response.data;
};"""
        if "export const addHouseItem" in api:
            print("SKIP: api item functions already present")
        elif api.count(sell_old) == 1:
            api = api.replace(sell_old, sell_new, 1)
            API.write_text(api)
            print("OK: api item functions added")
        else:
            print(f"WARNING: sellHouse anchor matched {api.count(sell_old)}x")

    # 6. index.tsx api imports.
    src = INDEX.read_text()
    imp_old = """  sendFriendRequest,
} from '../../services/api';"""
    imp_new = """  sendFriendRequest,
  addHouseItem,
  removeHouseItem,
} from '../../services/api';"""
    if imp_new in src:
        print("SKIP: api imports already present")
    elif src.count(imp_old) == 1:
        src = src.replace(imp_old, imp_new, 1)
        INDEX.write_text(src)
        print("OK: api imports added")
    else:
        print(f"WARNING: api import anchor matched {src.count(imp_old)}x")
    print("HOUSE_POOL_TABLE_OK")


if __name__ == "__main__":
    main()
